dark.dock:
QDockWidget {
    color: #f5f5f7;
}
QDockWidget::title {
    text-align: center;
    padding: 0px;
    background-color: #2c2c2e;
    color: #f5f5f7;
}
QWidget {
    background-color: #1c1c1e;
    color: #f5f5f7;
}
QListWidget {
    background-color: #1c1c1e;
    color: #f5f5f7;
    border: none;
    outline: none;
}
QListWidget::item {
    padding: 2px 0;
}
QListWidget::item:selected {
    background-color: #3a3a3c;
    color: #f5f5f7;
}
QListWidget::item:hover:!selected {
    background-color: #3a3a3c;
}
QListWidget#AnnotationFiles::item {
    padding: 1px 0;
    min-height: 18px;
}
QListWidget#AnnotationFiles::indicator {
    width: 14px;
    height: 14px;
    border-radius: 3px;
    border: 1px solid #48484a;
    background-color: #2c2c2e;
    margin-left: 2px;
    margin-right: 4px;
}
QListWidget#AnnotationFiles::indicator:hover {
    border-color: #3a3a3c;
}
QListWidget#AnnotationFiles::indicator:checked {
    background-color: #0A84FF;
    border: 1px solid #0A84FF;
    image: url(:/CC/plugin/qAnyLabeling/images/checkmark-white.svg);
}
QLineEdit {
    background-color: #2c2c2e;
    color: #f5f5f7;
    border: 1px solid #3a3a3c;
    border-radius: 6px;
    padding: 4px 8px;
    selection-background-color: #0A84FF;
}
QLineEdit:focus {
    border: 2px solid #409CFF;
}
QLabel {
    background-color: transparent;
    color: #f5f5f7;
}

QScrollBar:vertical {
    background-color: #2c2c2e;
    width: 8px;
    margin: 0;
}
QScrollBar::handle:vertical {
    background-color: #48484a;
    border-radius: 4px;
    min-height: 20px;
}
QScrollBar::handle:vertical:hover {
    background-color: #636366;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
}
QScrollBar:horizontal {
    background-color: #2c2c2e;
    height: 8px;
    margin: 0;
}
QScrollBar::handle:horizontal {
    background-color: #48484a;
    border-radius: 4px;
    min-width: 20px;
}
QScrollBar::handle:horizontal:hover {
    background-color: #636366;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
}
QScrollBar::add-page, QScrollBar::sub-page {
    background: transparent;
}
QAbstractScrollArea::corner {
    background-color: #2c2c2e;
    border: none;
}

QCheckBox {
    color: #f5f5f7;
}

QCheckBox::indicator {
    width: 16px;
    height: 16px;
    border-radius: 4px;
    border: 1px solid #48484a;
    background-color: #2c2c2e;
}
QCheckBox::indicator:hover {
    border-color: #0A84FF;
}
QCheckBox::indicator:checked {
    background-color: #0A84FF;
    border: 1px solid #0A84FF;
    image: url(:/CC/plugin/qAnyLabeling/images/checkmark-white.svg);
}

QPushButton {
    background-color: #2c2c2e;
    color: #f5f5f7;
    border: 1px solid #48484a;
    border-radius: 6px;
    padding: 3px 8px;
}
QPushButton:hover {
    background-color: #3a3a3c;
}
QPushButton:pressed {
    background-color: #48484a;
}
QComboBox {
    background-color: #2c2c2e;
    color: #f5f5f7;
    border: 1px solid #3a3a3c;
    border-radius: 6px;
    padding: 3px 8px;
}
QComboBox::drop-down {
    border: none;
    width: 20px;
}
QComboBox::down-arrow {
    image: url(:/CC/plugin/qAnyLabeling/images/caret-down.svg);
    width: 12px;
    height: 12px;
}
QComboBox QAbstractItemView {
    background-color: #2c2c2e;
    color: #f5f5f7;
    border: 1px solid #3a3a3c;
    border-radius: 0;
    padding: 0;
    margin: 0;
    selection-background-color: #0A84FF;
    selection-color: #ffffff;
}
QComboBox QAbstractItemView::item {
    background-color: #2c2c2e;
    padding: 4px 8px;
    min-height: 22px;
}
QComboBox QAbstractItemView::item:selected {
    background-color: #0A84FF;
    color: #ffffff;
}

